import { Component, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatStepperModule } from '@angular/material/stepper';

@Component({
  selector: 'app-signup-wizard',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    MatStepperModule,
    MatFormFieldModule,
    MatInputModule,
    MatButtonModule,
  ],
  templateUrl: './signup-wizard.component.html',
})
export class SignupWizardComponent {
  private fb = inject(FormBuilder);

  accountForm = this.fb.group({
    email: ['', [Validators.required, Validators.email]],
  });

  addressForm = this.fb.group({
    city: ['', Validators.required],
  });

  submit(): void {
    if (this.accountForm.invalid || this.addressForm.invalid) {
      this.accountForm.markAllAsTouched();
      this.addressForm.markAllAsTouched();
      return;
    }
    console.log({ ...this.accountForm.value, ...this.addressForm.value });
  }
}
